  ('pt-BR', 'whatsNew.item.orgExtensions.title', $json$"Servidores MCP e skills da organização"$json$::jsonb),
  ('en', 'whatsNew.item.orgExtensions.title', $json$"MCP servers and skills of the organization"$json$::jsonb),
