  ('en', 'site.org.mcp.delete.description', $json$"Members stop receiving this server at the app’s next sync."$json$::jsonb),
  ('es', 'site.org.mcp.delete.description', $json$"Los miembros dejan de recibir este servidor en la próxima sincronización de la app."$json$::jsonb),
  ('zh-CN', 'site.org.mcp.delete.description', $json$"成员将在应用下次同步时不再收到此服务器。"$json$::jsonb),
  ('hi', 'site.org.mcp.delete.description', $json$"ऐप के अगले सिंक में सदस्यों को यह सर्वर मिलना बंद हो जाएगा।"$json$::jsonb),
  ('ar', 'site.org.mcp.delete.description', $json$"يتوقف الأعضاء عن تلقي هذا الخادم عند المزامنة التالية للتطبيق."$json$::jsonb),
  ('fr', 'site.org.mcp.delete.description', $json$"Les membres ne recevront plus ce serveur à la prochaine synchronisation de l’app."$json$::jsonb),
  ('ru', 'site.org.mcp.delete.description', $json$"Участники перестанут получать этот сервер при следующей синхронизации приложения."$json$::jsonb),
  ('ja', 'site.org.mcp.delete.description', $json$"メンバーはアプリの次回の同期以降、このサーバーを受け取らなくなります。"$json$::jsonb),
