  ('ar', 'site.org.mcp.saved', $json$"تم حفظ الخادم. يتلقاه الأعضاء عند المزامنة التالية للتطبيق."$json$::jsonb),
  ('fr', 'site.org.mcp.saved', $json$"Serveur enregistré. Les membres le reçoivent à la prochaine synchronisation de l’app."$json$::jsonb),
