  ('fr', 'site.org.mcp.invalid.name', $json$"Utilisez uniquement des lettres, chiffres, - et _ (40 max). « jayv » est réservé."$json$::jsonb),
  ('ru', 'site.org.mcp.invalid.name', $json$"Только буквы, цифры, - и _ (до 40). «jayv» зарезервировано."$json$::jsonb),
  ('ja', 'site.org.mcp.invalid.name', $json$"英数字、- と _ のみ（40 文字まで）。「jayv」は予約済みです。"$json$::jsonb),
